options.customCss:
=@import url('https://fonts.googleapis.com/css2?family=Anton&family=Barlow:wght@400;500;600&display=swap');
/* Marca Container Lanches (specs/010-marca-e-pizzaria) — claro por padrão, escuro pelo sistema */
:root {
  --chat--color--primary: #F88E05;
  --chat--color--primary-shade-50: #E8790A;
  --chat--color--primary--shade-100: #D8660F;
  --chat--color--secondary: #F88E05;
  --chat--color-secondary-shade-50: #D8660F;
  --chat--color-white: #FFFFFF;
  --chat--color-light: #FBF5EC;
  --chat--color-light-shade-50: #F3E6D2;
  --chat--color-light-shade-100: #E6D3B8;
  --chat--color-medium: #E6D3B8;
  --chat--color-dark: #130B06;
  --chat--color-typing: #6B4F36;
  --chat--font-family: 'Barlow', system-ui, sans-serif;
  --chat--border-radius: 0.75rem;
  --chat--header--background: url('{{ $env.APP_URL }}/marca/logo-quadrada.png') no-repeat var(--chat--spacing) center / 64px 64px, #130B06;
  --chat--header--color: #F4E6CF;
  --chat--header--padding: var(--chat--spacing) var(--chat--spacing) var(--chat--spacing) calc(var(--chat--spacing) + 76px);
  --chat--header--border-bottom: 4px solid #F88E05;
  --chat--input--container--background: #FFFFFF;
  --chat--input--container--border: 1px solid #E6D3B8;
  --chat--heading--font-size: 2.2em;
  --chat--message--bot--background: #FFFFFF;
  --chat--message--bot--color: #211209;
  --chat--message--user--background: #F88E05;
  --chat--message--user--color: #1A0E06;
  --chat--body--background: #FBF5EC;
  --chat--footer--background: #FBF5EC;
  --chat--footer--color: #211209;
  --chat--input--background: #FFFFFF;
  --chat--input--text-color: #211209;
  --chat--input--send--button--background: #FFFFFF;
  --chat--input--send--button--color: #D8660F;
  --chat--input--send--button--background-hover: #FCE7C3;
  --chat--input--send--button--color-hover: #D8660F;
  --chat--button--background--primary: #F88E05;
  --chat--button--color--primary: #1A0E06;
}
@media (prefers-color-scheme: dark) {
  :root {
    --chat--color-light: #1E120A;
    --chat--color-light-shade-50: #26170D;
    --chat--color-light-shade-100: #3A2616;
    --chat--color-medium: #3A2616;
    --chat--color-typing: #C9AE8C;
    --chat--message--bot--background: #26170D;
    --chat--message--bot--color: #F4E6CF;
    --chat--body--background: #130B06;
    --chat--footer--background: #130B06;
    --chat--footer--color: #F4E6CF;
    --chat--input--background: #1E120A;
    --chat--input--text-color: #F4E6CF;
    --chat--input--send--button--background: #1E120A;
    --chat--input--send--button--color: #F88E05;
    --chat--input--send--button--background-hover: #2E1C10;
    --chat--input--container--background: #1E120A;
    --chat--input--container--border: 1px solid #3A2616;
  }
}
.chat-layout .chat-header {
  min-height: 96px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.chat-layout .chat-header h1 {
  margin: 0;
  font-family: 'Anton', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  background: linear-gradient(180deg, #FFB347 0%, #F88E05 45%, #E8590C 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.chat-layout .chat-header p {
  margin: 0;
  color: #EFD7B1;
  letter-spacing: 0.06em;
}
.chat-message {
  max-width: 80%;
}
.chat-message-from-bot {
  border: 1px solid var(--chat--color-light-shade-100);
}
